1	// Every render the pipeline produces is written into a directory the script
2	// creates for itself (measure_vessels.py --overlays -> analysis/overlays/,
3	// annotate_overlays.py -> analysis/annotated/). Those directories are gitignored,
4	// which is what makes "regenerate, never commit" hold under a `git add -A` or an
5	// agent staging a whole directory.
6	//
7	// Sibling of rendered-overlays-untracked, from the other side: that rule fires once
8	// a render is already tracked (the damage), this one keeps the ignore entry that
9	// stops it getting there. A newly added output directory is the real gap — it is
10	// gitignored only if someone remembers, and nothing said so until now.
11	//
12	// Parse rather than grep: an output directory is one the script actually creates
13	// (`os.makedirs(...)`), resolved through the script's own `HERE` constant, with
14	// comments and string literals handled — a path mentioned in a docstring is not a
15	// directory anything writes to.
16	const SHARED = '.claudinite/shared/';        // read-only mounted canon
17	const HERE_DEF = /^\s*HERE\s*=\s*os\.path\.dirname\(\s*os\.path\.abspath\(\s*__file__\s*\)\s*\)/m;
18	// NAME = os.path.join(HERE, 'annotated')  /  os.path.join(HERE, 'a', 'b')
19	const JOIN = /(?:^|[^\w.])([A-Za-z_]\w*)\s*=\s*os\.path\.join\(\s*HERE\s*,\s*((?:'[^']*'|"[^"]*")(?:\s*,\s*(?:'[^']*'|"[^"]*"))*)\s*\)/g;
20	const MAKEDIRS = /os\.makedirs\(\s*([A-Za-z_]\w*)\b/g;
21	const PARTS = /'([^']*)'|"([^"]*)"/g;
22	
23	// Comments stripped, string literals kept: the joined path segments ARE literals,
24	// so this only removes `#` runs that are not inside a string.
25	function uncomment(text) {
26	  return text.split('\n').map((line) => {
27	    let quote = null;
28	    for (let i = 0; i < line.length; i += 1) {
29	      const c = line[i];
30	      if (quote) {
31	        if (c === '\\') i += 1;
32	        else if (c === quote) quote = null;
33	      } else if (c === '"' || c === "'") quote = c;
34	      else if (c === '#') return line.slice(0, i);
35	    }
36	    return line;
37	  }).join('\n');
38	}
39	
40	const dirOf = (file) => (file.includes('/') ? file.slice(0, file.lastIndexOf('/')) : '');
41	const joinPath = (...ps) => ps.filter(Boolean).join('/');
42	
43	// The directories a script creates under its own location, as repo-relative paths
44	// with the line of the makedirs call. Empty unless HERE is the script's own dir —
45	// an unrecognised layout is left alone rather than guessed at.
46	function createdDirs(file, source) {
47	  const text = uncomment(source);
48	  if (!HERE_DEF.test(text)) return [];
49	  const here = dirOf(file);
50	  const consts = new Map();
51	  for (const m of text.matchAll(JOIN)) {
52	    const segs = [...m[2].matchAll(PARTS)].map((p) => p[1] ?? p[2]);
53	    if (segs.some((s) => s === '..' || s === '')) continue;   // escapes the script's dir
54	    consts.set(m[1], joinPath(here, ...segs));
55	  }
56	  const out = new Map();
57	  for (const m of text.matchAll(MAKEDIRS)) {
58	    const path = consts.get(m[1]);
59	    if (!path || out.has(path)) continue;
60	    out.set(path, { path, name: m[1], line: text.slice(0, m.index).split('\n').length });
61	  }
62	  return [...out.values()];
63	}
64	
65	// The ignore patterns that can cover `dir`: git reads a .gitignore per directory,
66	// so every ancestor of `dir` gets one — root first, deepest last, which is also
67	// git's precedence order (the last matching pattern wins). A .gitignore *inside*
68	// `dir` is excluded: it cannot cause its own directory to be ignored. Each entry
69	// is returned as { path, negated, anchored }, normalised to a repo-relative path
70	// or a bare name git matches at any depth below that .gitignore's directory.
71	function patterns(ctx, dir) {
72	  const segs = dir.split('/').slice(0, -1);
73	  const bases = ['', ...segs.map((_, i) => segs.slice(0, i + 1).join('/'))];
74	  const out = [];
75	  for (const base of new Set(bases)) {
76	    const text = ctx.read(joinPath(base, '.gitignore'));
77	    if (text === null) continue;
78	    for (const raw of text.split('\n')) {
79	      const line = raw.trim();
80	      if (!line || line.startsWith('#')) continue;
